def trs(pts):
    # normalized shape bounding box
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    norm=((r-r0,c-c0) for r,c in pts)
    res=[]
    for name,tfn in [('id',lambda x:x),('vflip',lambda x:(x[0],-x[1])),('hflip',lambda x:(-x[0],x[1])),('rot90',lambda x:(x[1],x[0])),('rot180',lambda x:(-x[0],-x[1])),('rot270',lambda x:(-x[1],x[0])),('T',lambda x:(x[1],x[0]))]:
        n=tfn(norm)
        mn=(m for m in (r for r,c in n)); 
        # normalize again so bbox at 0
        nn=((r-min(r for r,_ in n), c-min(c for _,c in n)) for r,c in n)
        res.append((name,n))
    return res
